-- 026: crawl gate, conditional-GET validators, text fingerprint, realness score (2026-10-01).
-- Generated by mix run from LS.DNS.Parking.sql/1 and LS.Schema.Realness; apply with 026_crawl_gate_realness.sh.
ALTER TABLE enrich_log ADD COLUMN IF NOT EXISTS http_etag String DEFAULT '', ADD COLUMN IF NOT EXISTS http_last_modified String DEFAULT '', ADD COLUMN IF NOT EXISTS http_body_simhash UInt64 DEFAULT 0;
ALTER TABLE businesses ADD COLUMN IF NOT EXISTS http_etag String DEFAULT '', ADD COLUMN IF NOT EXISTS http_last_modified String DEFAULT '', ADD COLUMN IF NOT EXISTS http_body_simhash UInt64 DEFAULT 0, ADD COLUMN IF NOT EXISTS estimated_realness Float32 DEFAULT 0, ADD COLUMN IF NOT EXISTS estimated_realness_evidence String DEFAULT '';
-- Parking nameservers: 132K businesses measured with an empty junk flag on 2026-10-01.
ALTER TABLE businesses UPDATE estimated_junk = 'parked' WHERE estimated_junk = '' AND arrayExists(ns -> arrayExists(m -> ns = m OR endsWith(ns, concat('.', m)), ['sedoparking.com', 'dovendi.nl', 'dovendi.eu', 'thisdomain.forsale', 'bodis.com', 'parkingcrew.net', 'afternic.com', 'dan.com', 'undeveloped.com', 'uniregistrymarket.link', 'above.com', 'parklogic.com', 'cashparking.com', 'namedrive.com', 'smartname.com', 'brainydns.com', 'eftydns.com', 'squadhelp.com', 'parktons.com', 'hastydns.com', 'rookdns.com', 'trafficz.com', 'internettraffic.com', 'voodoo.com', 'ztomy.com', 'sav.com', 'parkingpage.namecheap.com', 'domainmarket.com', 'buydomains.com', 'hugedomains.com', 'sedo.com']), arrayMap(x -> trimRight(lower(x), '.'), rdap_nameservers));
-- Realness backfill over every compiled row; the fold maintains it from here on.
ALTER TABLE businesses UPDATE estimated_realness = toFloat32(if(estimated_junk != '', 0, least(1.0, if(notEmpty(dns_mx), 0.15, 0) + if(dns_dmarc != '', 0.05, 0) + if((notEmpty(http_emails) OR http_phone != ''), 0.15, 0) + if(http_address != '', 0.05, 0) + if(http_company_id != '', 0.15, 0) + if(http_schema_type IN ('Organization', 'LocalBusiness', 'Corporation', 'Store', 'OnlineStore', 'ProfessionalService', 'Restaurant', 'MedicalBusiness', 'FinancialService', 'EducationalOrganization', 'TravelAgency', 'RealEstateAgent', 'LegalService', 'HomeAndConstructionBusiness', 'AutoDealer', 'AutomotiveBusiness', 'SportsActivityLocation', 'HealthAndBeautyBusiness', 'FoodEstablishment', 'LodgingBusiness', 'Dentist', 'Physician', 'Hotel'), 0.1, 0) + if(ctl_first_seen_at < now() - INTERVAL 90 DAY, 0.1, 0) + if((coalesce(shop_product_count, 0) > 0 OR coalesce(hr_job_count, 0) > 0), 0.1, 0) + if((tranco_rank IS NOT NULL OR majestic_rank IS NOT NULL), 0.1, 0) + if(notEmpty(http_social_links), 0.05, 0) + if(verified_at IS NOT NULL, 0.1, 0)))), estimated_realness_evidence = if(estimated_junk != '', '', arrayStringConcat(arrayFilter(x -> x != '', [if(notEmpty(dns_mx), 'mx', ''), if(dns_dmarc != '', 'dmarc', ''), if((notEmpty(http_emails) OR http_phone != ''), 'contact', ''), if(http_address != '', 'address', ''), if(http_company_id != '', 'company_id', ''), if(http_schema_type IN ('Organization', 'LocalBusiness', 'Corporation', 'Store', 'OnlineStore', 'ProfessionalService', 'Restaurant', 'MedicalBusiness', 'FinancialService', 'EducationalOrganization', 'TravelAgency', 'RealEstateAgent', 'LegalService', 'HomeAndConstructionBusiness', 'AutoDealer', 'AutomotiveBusiness', 'SportsActivityLocation', 'HealthAndBeautyBusiness', 'FoodEstablishment', 'LodgingBusiness', 'Dentist', 'Physician', 'Hotel'), 'schema_org', ''), if(ctl_first_seen_at < now() - INTERVAL 90 DAY, 'age_90d', ''), if((coalesce(shop_product_count, 0) > 0 OR coalesce(hr_job_count, 0) > 0), 'activity', ''), if((tranco_rank IS NOT NULL OR majestic_rank IS NOT NULL), 'traffic', ''), if(notEmpty(http_social_links), 'social', ''), if(verified_at IS NOT NULL, 'registry', '')]), '|')) WHERE 1;
